import{_ as i,a0 as p,w as o,s as d,ao as a,I as l,x as n,a1 as u,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"每日 Ubuntu 小技巧：怎样在Ubuntu升级新的 Linux Kernel 3.12.7 | LCTT x X-CMD","titleTemplate":false,"description":"每日 Ubuntu 小技巧：怎样在Ubuntu升级新的 Linux Kernel 3.12.7 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日 Ubuntu 小技巧：怎样在Ubuntu升级新的 Linux Kernel 3.12.7 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日 Ubuntu 小技巧：怎样在Ubuntu升级新的 Linux Kernel 3.12.7 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Daily Ubuntu Tips – Linux Kernel 3.12.7 Released – Here’s How To Upgrade In Ubuntu","title":"每日 Ubuntu 小技巧：怎样在Ubuntu升级新的 Linux Kernel 3.12.7","tag":"201403","desc":""},"relativePath":"201403/Daily Ubuntu Tips – Linux Kernel 3.12.7 Released – Here’s How To Upgrade In Ubuntu.md","filePath":"[post].md"}'),s={name:"201403/Daily Ubuntu Tips – Linux Kernel 3.12.7 Released – Here’s How To Upgrade In Ubuntu.md"};function b(m,e,x,_,g,k){const t=p("Link");return o(),d("div",null,[e[14]||(e[14]=a('<h1 id="每日-ubuntu-小技巧-怎样在ubuntu升级新的-linux-kernel-3-12-7" tabindex="-1">每日 Ubuntu 小技巧：怎样在Ubuntu升级新的 Linux Kernel 3.12.7 <a class="header-anchor" href="#每日-ubuntu-小技巧-怎样在ubuntu升级新的-linux-kernel-3-12-7" aria-label="Permalink to “每日 Ubuntu 小技巧：怎样在Ubuntu升级新的 Linux Kernel 3.12.7”">​</a></h1><p>Linux Kernel 版本3.12.7主线已经发布了，而这篇简短教程将会向你展示怎样简单地在 Ubuntu 中升级。如果你正好运行 Ubuntu 13.10 或者更低版本，还碰巧你的系统还不是安装最新的内核，读完吧。</p><p>Linux Kernel 是 linux 操作系统的核心，包括了 Ubuntu。内核使 Ubuntu 可以与系统硬件（内存，CPU，设备等等）通信。内核管理资源并掌管你机器设备的所有重要部分。</p><p>没有 Linux Kernel， Ubuntu 只是一串幻想应用而不能连接硬件或者你机器所有的重要部分。这就是为什么Linux Kernel 如此的重要。</p><h3 id="为什么升级你的-ubuntu-kernel" tabindex="-1">为什么升级你的 Ubuntu Kernel? <a class="header-anchor" href="#为什么升级你的-ubuntu-kernel" aria-label="Permalink to “为什么升级你的 Ubuntu Kernel?”">​</a></h3><p>在升级你的系统内核之前，第一件需要知道的事情就是升级可能会破坏你的系统，使它无法使用。事实上，并不推荐你自己升级内核。Ubuntu 的总公司 Canonical 在 Ubuntu 内核升级上做得很好。</p><p>在新版本发布之前，他们测试并且确定内核的安装是兼容的。所以，如果你的设备工作良好，没有问题，你应该保持现有内核，不要升级。</p><p>另一方面，如果 Ubuntu 不能识别所有系统的元件或者你的设备功能不正确，升级 Linux kernel 也许会有帮助。</p><p>这是因为新的内核为你的新机器增加了新的驱动和功能。如果现在安装的内核不支持机器上的某些功能，你应该升级一下。</p>',9)),l("p",null,[e[1]||(e[1]=n("更多关于内核3.12.7，",-1)),u(t,{href:"https://www.kernel.org/pub/linux/kernel/v3.x/ChangeLog-3.12.7"},{default:r(()=>[...e[0]||(e[0]=[n("点这里阅读更新日志",-1)])]),_:1}),e[2]||(e[2]=n("。",-1))]),e[15]||(e[15]=a(`<h3 id="现在升级-linux-kernel" tabindex="-1">现在升级 Linux Kernel <a class="header-anchor" href="#现在升级-linux-kernel" aria-label="Permalink to “现在升级 Linux Kernel”">​</a></h3><p>要想升级你的内核，运行下列命令来升级所有安装包和现存内核。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade &amp;&amp; sudo apt-get autoremove
</code></pre><p>升级完成后，重启你的设备。在安装完系统包和内核后重启机器是一个好习惯。这样做是为了让新的内核能够被应用。</p><p>接下来，运行下列命令来下载 Linux Kernel 3.12.7</p><h4 id="_32位设备-运行下列命令" tabindex="-1">32位设备，运行下列命令 <a class="header-anchor" href="#_32位设备-运行下列命令" aria-label="Permalink to “32位设备，运行下列命令”">​</a></h4><pre><code>cd /tmp &amp;&amp; wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-headers-3.12.7-031207-generic_3.12.7-031207.201401091657_i386.deb http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-headers-3.12.7-031207_3.12.7-031207.201401091657_all.deb http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-image-3.12.7-031207-generic_3.12.7-031207.201401091657_i386.deb
</code></pre><h4 id="_64位设备-运行下列命令" tabindex="-1">64位设备，运行下列命令 <a class="header-anchor" href="#_64位设备-运行下列命令" aria-label="Permalink to “64位设备，运行下列命令”">​</a></h4><pre><code>cd /tmp &amp;&amp; wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-headers-3.12.7-031207-generic_3.12.7-031207.201401091657_amd64.deb http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-headers-3.12.7-031207_3.12.7-031207.201401091657_all.deb http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-image-3.12.7-031207-generic_3.12.7-031207.201401091657_amd64.deb
</code></pre><p>下载你的系统对应版本后，运行下列命令</p><pre><code>sudo dpkg -i *.deb
</code></pre><p>安装完成后，重启你的设备，如果一切都按照上面描述一样进展顺利，你的系统应该拥有了最新稳定的内核版本。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/linuxkernel3127.jpg" alt=""></p><p>卸载内核3.12.7版本，使用下列命令</p><pre><code>sudo apt-get remove linux-headers-3.12.7-* linux-image-3.13.7-*
</code></pre><p>好好享受吧！</p><hr>`,17)),l("p",null,[e[4]||(e[4]=n("via: ",-1)),u(t,{href:"http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-linux-kernel-3-12-7-released-heres-how-to-upgrade-in-ubuntu/"},{default:r(()=>[...e[3]||(e[3]=[n("http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-linux-kernel-3-12-7-released-heres-how-to-upgrade-in-ubuntu/",-1)])]),_:1})]),l("p",null,[e[7]||(e[7]=n("译者：",-1)),u(t,{href:"http://blog.csdn.net/Vic___"},{default:r(()=>[...e[5]||(e[5]=[n("Vic___",-1)])]),_:1}),e[8]||(e[8]=n(" 校对：",-1)),u(t,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...e[6]||(e[6]=[n("Caroline",-1)])]),_:1})]),l("p",null,[e[11]||(e[11]=n("本文由 ",-1)),u(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[9]||(e[9]=[n("LCTT",-1)])]),_:1}),e[12]||(e[12]=n(" 原创翻译，",-1)),u(t,{href:"http://linux.cn/"},{default:r(()=>[...e[10]||(e[10]=[n("Linux中国",-1)])]),_:1}),e[13]||(e[13]=n(" 荣誉推出",-1))])])}const L=i(s,[["render",b]]);export{h as __pageData,L as default};
